element.style.position = 'relative';

if (element.querySelector('.custom-save-btn')) return;

var btn = document.createElement('button');
btn.className = 'custom-save-btn';
btn.type = 'button';
btn.setAttribute('aria-label', 'Save to Board');
btn.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="white"><path d="M16 1H8C6.34 1 5 2.34 5 4v16l7-3 7 3V4c0-1.66-1.34-3-3-3z"/></svg> Save';

btn.style.cssText = 'position:absolute;top:10px;right:10px;z-index:10;' +
  'background:#e60023;color:white;border:none;border-radius:20px;' +
  'padding:8px 14px;font-size:13px;font-weight:700;cursor:pointer;' +
  'display:flex;align-items:center;gap:5px;' +
  'box-shadow:0 2px 8px rgba(0,0,0,0.3);' +
  'transition:background 0.2s,transform 0.1s;' +
  'pointer-events:auto;';

btn.addEventListener('mouseenter', function() {
  btn.style.background = '#ad081b';
  btn.style.transform = 'scale(1.05)';
});
btn.addEventListener('mouseleave', function() {
  btn.style.background = '#e60023';
  btn.style.transform = 'scale(1)';
});
btn.addEventListener('mousedown', function() {
  btn.style.transform = 'scale(0.97)';
});
btn.addEventListener('mouseup', function() {
  btn.style.transform = 'scale(1.05)';
});

element.appendChild(btn);
